'use client';

import { useEffect, useRef } from 'react';

/*
 * Full 6-step EMAP merchant signup form as a Next.js Client Component.
 * Pure client-side — every step is POSTed directly from the browser to
 * EMAP's API via fetch(). There is no app/api/*.ts route anywhere in this
 * integration and none is needed: EMAP's API sets CORS headers that allow
 * being called directly from a browser (Access-Control-Allow-Origin
 * reflects any Origin), so no server-side proxy exists.
 *
 * The markup and logic below are intentionally identical to
 * templates/integration-1/plain-html.html (the same tested implementation)
 * — mounted imperatively into a container ref rather than rewritten as
 * JSX/hooks, so this component's behavior is guaranteed to match that
 * already-verified version instead of introducing a second, untested
 * reimplementation of 150+ fields and 6 steps of conditional logic.
 *
 * EDIT EMAP_BASE_URL / EMAP_PARTNER_KEY inside FORM_LOGIC below (search for
 * "EDIT THESE") before deploying — same as in plain-html.html.
 */

const FORM_CSS: string = "\n    *, *::before, *::after { box-sizing: border-box; }\n\n    body {\n      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;\n      background: #f5f7fa;\n      color: #1a1a2e;\n      margin: 0;\n      padding: 40px 16px;\n    }\n\n    .card {\n      max-width: 640px;\n      margin: 0 auto;\n      background: #fff;\n      border-radius: 12px;\n      box-shadow: 0 4px 24px rgba(0,0,0,.08);\n      padding: 40px 36px;\n    }\n\n    /* Progress bar */\n    .progress-bar {\n      display: flex;\n      align-items: center;\n      margin-bottom: 32px;\n      gap: 0;\n    }\n    .progress-step {\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      flex: 1;\n      position: relative;\n    }\n    .progress-step:not(:last-child)::after {\n      content: '';\n      position: absolute;\n      top: 14px;\n      left: 50%;\n      width: 100%;\n      height: 2px;\n      background: #e5e7eb;\n      z-index: 0;\n    }\n    .progress-step.done::after, .progress-step.active::after { background: #3b82f6; }\n    .step-circle {\n      width: 28px;\n      height: 28px;\n      border-radius: 50%;\n      background: #e5e7eb;\n      color: #9ca3af;\n      font-size: .75rem;\n      font-weight: 700;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      position: relative;\n      z-index: 1;\n    }\n    .progress-step.active .step-circle { background: #3b82f6; color: #fff; }\n    .progress-step.done .step-circle { background: #10b981; color: #fff; }\n    .step-label {\n      font-size: .65rem;\n      color: #9ca3af;\n      margin-top: 4px;\n      text-align: center;\n      white-space: nowrap;\n    }\n    .progress-step.active .step-label { color: #3b82f6; font-weight: 600; }\n    .progress-step.done .step-label { color: #10b981; }\n\n    h2 { font-size: 1.4rem; margin: 0 0 4px; color: #0f172a; }\n    .step-subtitle { color: #64748b; margin: 0 0 24px; font-size: .9rem; }\n\n    .form-row { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }\n    .form-group { margin-bottom: 16px; }\n    .form-section { margin-top: 24px; margin-bottom: 8px; border-top: 1px solid #e5e7eb; padding-top: 20px; }\n    .form-section h3 { font-size: .9rem; font-weight: 700; color: #374151; margin: 0 0 16px; text-transform: uppercase; letter-spacing: .04em; }\n\n    label {\n      display: block;\n      font-size: .85rem;\n      font-weight: 600;\n      color: #374151;\n      margin-bottom: 5px;\n    }\n    label .required { color: #ef4444; margin-left: 2px; }\n    label .hint { font-weight: 400; color: #6b7280; font-size: .8rem; }\n\n    input:not([type=\"checkbox\"]):not([type=\"radio\"]):not([type=\"range\"]), select, textarea {\n      width: 100%;\n      padding: 10px 13px;\n      border: 1.5px solid #d1d5db;\n      border-radius: 7px;\n      font-size: .95rem;\n      color: #1f2937;\n      background: #fff;\n      transition: border-color .15s;\n      appearance: none;\n      font-family: inherit;\n    }\n    textarea { resize: vertical; min-height: 80px; }\n    input:not([type=\"checkbox\"]):not([type=\"radio\"]):not([type=\"range\"]):focus, select:focus, textarea:focus {\n      outline: none;\n      border-color: #3b82f6;\n      box-shadow: 0 0 0 3px rgba(59,130,246,.15);\n    }\n    input:not([type=\"checkbox\"]):not([type=\"radio\"]).error, select.error, textarea.error { border-color: #ef4444; }\n    .field-error { display: block; color: #ef4444; font-size: .8rem; margin-top: 4px; }\n\n    .checkbox-group { display: flex; flex-direction: column; gap: 8px; }\n    .checkbox-item { display: flex; align-items: center; gap: 10px; }\n    .checkbox-item input[type=\"checkbox\"] { width: 16px; height: 16px; flex-shrink: 0; cursor: pointer; }\n    .checkbox-item label { font-weight: 400; color: #374151; cursor: pointer; margin-bottom: 0; }\n\n    .radio-group { display: flex; gap: 20px; flex-wrap: wrap; }\n    .radio-item { display: flex; align-items: center; gap: 8px; }\n    .radio-item input[type=\"radio\"] { width: 16px; height: 16px; cursor: pointer; }\n    .radio-item label { font-weight: 400; cursor: pointer; margin-bottom: 0; }\n\n    .pct-sliders { display: flex; flex-direction: column; gap: 14px; margin-top: 8px; }\n    .pct-slider-row { display: grid; grid-template-columns: 170px 1fr 44px; align-items: center; gap: 12px; }\n    .pct-slider-row label { font-size: .85rem; font-weight: 500; color: #374151; margin: 0; }\n    .pct-slider-row input[type=\"range\"] { width: 100%; accent-color: #3b82f6; cursor: pointer; height: 4px; }\n    .pct-val { font-size: .92rem; font-weight: 600; color: #1d4ed8; text-align: right; white-space: nowrap; }\n    .pct-sum-note { font-size: .8rem; color: #6b7280; margin-top: 6px; }\n    .pct-sum-note.error { color: #ef4444; }\n\n    .terms-box { width: 100%; height: 220px; font-size: .78rem; line-height: 1.55; color: #374151; background: #f9fafb; border: 1.5px solid #d1d5db; border-radius: 7px; padding: 12px 14px; resize: none; font-family: inherit; overflow-y: scroll; }\n    .terms-box:focus { outline: none; border-color: #3b82f6; }\n\n    .terms-group { margin: 20px 0; display: flex; align-items: flex-start; gap: 10px; }\n    .terms-group input[type=\"checkbox\"] { width: 17px; height: 17px; flex-shrink: 0; margin-top: 2px; cursor: pointer; }\n    .terms-group label { font-size: .88rem; font-weight: 400; color: #4b5563; cursor: pointer; }\n    .terms-group a { color: #3b82f6; }\n\n    .btn-row { display: flex; gap: 12px; margin-top: 24px; }\n    button[type=\"button\"].btn-back {\n      flex: 0 0 auto;\n      padding: 12px 20px;\n      background: #f3f4f6;\n      color: #374151;\n      border: 1.5px solid #d1d5db;\n      border-radius: 8px;\n      font-size: .95rem;\n      font-weight: 600;\n      cursor: pointer;\n    }\n    button[type=\"button\"].btn-back:hover { background: #e5e7eb; }\n    button[type=\"submit\"] {\n      flex: 1;\n      padding: 13px;\n      background: #3b82f6;\n      color: #fff;\n      border: none;\n      border-radius: 8px;\n      font-size: 1rem;\n      font-weight: 600;\n      cursor: pointer;\n      transition: background .15s, opacity .15s;\n    }\n    button[type=\"submit\"]:hover:not(:disabled) { background: #2563eb; }\n    button[type=\"submit\"]:disabled { opacity: .65; cursor: not-allowed; }\n\n    .alert { padding: 12px 16px; border-radius: 7px; margin-bottom: 20px; font-size: .9rem; }\n    .alert-error   { background: #fef2f2; color: #991b1b; border: 1px solid #fecaca; }\n    .alert-warning { background: #fffbeb; color: #92400e; border: 1px solid #fde68a; }\n\n    .step-section { display: none; }\n    .step-section.active { display: block; }\n\n    #success-panel { display: none; text-align: center; padding: 20px 0; }\n    #success-panel .icon { font-size: 3.5rem; margin-bottom: 12px; }\n    #success-panel h2 { color: #166534; margin: 0 0 8px; }\n    #success-panel p { color: #4b5563; }\n\n    .sensitive-note { font-size: .75rem; color: #6b7280; margin-top: 4px; }\n\n    .hp-field { display: none !important; }\n\n    @media (max-width: 520px) {\n      .card { padding: 28px 20px; }\n      .form-row, .pct-row { grid-template-columns: 1fr; }\n      .step-label { display: none; }\n    }\n  ";

const FORM_HTML: string = "<div class=\"card\">\n\n    <!-- Progress bar -->\n    <div class=\"progress-bar\" id=\"progress-bar\">\n      <div class=\"progress-step active\" data-step=\"1\"><div class=\"step-circle\">1</div><div class=\"step-label\">Basics</div></div>\n      <div class=\"progress-step\" data-step=\"2\"><div class=\"step-circle\">2</div><div class=\"step-label\">Company</div></div>\n      <div class=\"progress-step\" data-step=\"3\"><div class=\"step-circle\">3</div><div class=\"step-label\">Products</div></div>\n      <div class=\"progress-step\" data-step=\"4\"><div class=\"step-circle\">4</div><div class=\"step-label\">Owners</div></div>\n      <div class=\"progress-step\" data-step=\"5\"><div class=\"step-circle\">5</div><div class=\"step-label\">Banking</div></div>\n      <div class=\"progress-step\" data-step=\"6\"><div class=\"step-circle\">6</div><div class=\"step-label\">Final</div></div>\n    </div>\n\n    <div id=\"form-alert\" class=\"alert\" style=\"display:none\"></div>\n\n    <!-- \u2500\u2500 Step 1: Contact & Business Basics \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n    <form id=\"form-step1\" class=\"step-section active\" novalidate>\n      <input class=\"hp-field\" name=\"_hp\" tabindex=\"-1\" autocomplete=\"off\">\n      <h2>Contact &amp; Business Basics</h2>\n      <p class=\"step-subtitle\">Tell us about yourself and your company.</p>\n\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label for=\"first_name\">First Name <span class=\"required\">*</span></label>\n          <input id=\"first_name\" name=\"first_name\" type=\"text\" maxlength=\"255\" autocomplete=\"given-name\" required>\n          <span class=\"field-error\" id=\"err_first_name\"></span>\n        </div>\n        <div class=\"form-group\">\n          <label for=\"last_name\">Last Name <span class=\"required\">*</span></label>\n          <input id=\"last_name\" name=\"last_name\" type=\"text\" maxlength=\"255\" autocomplete=\"family-name\" required>\n          <span class=\"field-error\" id=\"err_last_name\"></span>\n        </div>\n      </div>\n\n      <div class=\"form-group\">\n        <label for=\"email\">Email Address <span class=\"required\">*</span></label>\n        <input id=\"email\" name=\"email\" type=\"email\" maxlength=\"255\" autocomplete=\"email\" required>\n        <span class=\"field-error\" id=\"err_email\"></span>\n      </div>\n\n      <div class=\"form-group\">\n        <label for=\"phone\">Phone Number <span class=\"required\">*</span></label>\n        <input id=\"phone\" name=\"phone\" type=\"tel\" maxlength=\"20\" autocomplete=\"tel\" placeholder=\"+1 202 555 1234\" required>\n        <span class=\"field-error\" id=\"err_phone\"></span>\n      </div>\n\n      <div class=\"form-group\">\n        <label for=\"company_name\">Company Name <span class=\"required\">*</span></label>\n        <input id=\"company_name\" name=\"company_name\" type=\"text\" maxlength=\"255\" autocomplete=\"organization\" required>\n        <span class=\"field-error\" id=\"err_company_name\"></span>\n      </div>\n\n      <div class=\"form-group\">\n        <label for=\"website\">Company Website <span class=\"required\">*</span></label>\n        <input id=\"website\" name=\"website\" type=\"url\" maxlength=\"255\" autocomplete=\"url\" placeholder=\"https://yourcompany.com\" required>\n        <span class=\"field-error\" id=\"err_website\"></span>\n      </div>\n\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label for=\"country\">Formation Country <span class=\"required\">*</span></label>\n          <select id=\"country\" name=\"country\" required>\n            <option value=\"\">Loading countries\u2026</option>\n          </select>\n          <span class=\"field-error\" id=\"err_country\"></span>\n        </div>\n        <div class=\"form-group\" id=\"state_group\" style=\"display:none\">\n          <label for=\"business_state\">Formation State <span class=\"required\">*</span></label>\n          <select id=\"business_state\" name=\"business_state\">\n            <option value=\"\">Select state\u2026</option>\n          </select>\n          <span class=\"field-error\" id=\"err_business_state\"></span>\n        </div>\n      </div>\n\n      <div class=\"form-group\">\n        <label for=\"annual_sales\">Estimated Annual Sales (USD) <span class=\"required\">*</span></label>\n        <input id=\"annual_sales\" name=\"annual_sales\" type=\"number\" min=\"1\" required placeholder=\"e.g. 500000\">\n        <span class=\"field-error\" id=\"err_annual_sales\"></span>\n      </div>\n\n      <div class=\"form-group\">\n        <label for=\"industry_type\">Industry Type <span class=\"required\">*</span></label>\n        <select id=\"industry_type\" name=\"industry_type\" required>\n          <option value=\"\">Loading industries\u2026</option>\n        </select>\n        <span class=\"field-error\" id=\"err_industry_type\"></span>\n      </div>\n\n      <div class=\"form-group\" id=\"industry_type_other_group\" style=\"display:none\">\n        <label for=\"industry_type_other\">Describe your industry <span class=\"required\">*</span></label>\n        <input id=\"industry_type_other\" name=\"industry_type_other\" type=\"text\" maxlength=\"255\" placeholder=\"Briefly describe your industry\">\n        <span class=\"field-error\" id=\"err_industry_type_other\"></span>\n      </div>\n\n      <div class=\"form-group\">\n        <label for=\"promo_code\">Referral / Promo Code <span class=\"hint\">(optional)</span></label>\n        <input id=\"promo_code\" name=\"promo_code\" type=\"text\" maxlength=\"255\" autocomplete=\"off\">\n      </div>\n\n      <div class=\"btn-row\">\n        <button type=\"submit\" id=\"btn-step1\">Continue \u2014 Company Info \u2192</button>\n      </div>\n    </form>\n\n    <!-- \u2500\u2500 Step 2: Company Information \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n    <form id=\"form-step2\" class=\"step-section\" novalidate>\n      <h2>Company Information</h2>\n      <p class=\"step-subtitle\">Legal structure, address, and revenue model.</p>\n\n      <div class=\"form-group\">\n        <label for=\"legal_name\">Legal Company Name <span class=\"required\">*</span></label>\n        <input id=\"legal_name\" name=\"legal_name\" type=\"text\" maxlength=\"255\" required>\n        <span class=\"field-error\" id=\"err_legal_name\"></span>\n      </div>\n\n      <div class=\"form-group\">\n        <label for=\"dba_name\">DBA / Trading Name <span class=\"required\">*</span></label>\n        <input id=\"dba_name\" name=\"name\" type=\"text\" maxlength=\"255\" required>\n        <span class=\"field-error\" id=\"err_name\"></span>\n      </div>\n\n      <div class=\"form-group\">\n        <label for=\"customer_service_telephone_number\">Customer Service Phone <span class=\"required\">*</span></label>\n        <input id=\"customer_service_telephone_number\" name=\"customer_service_telephone_number\" type=\"tel\" maxlength=\"20\" placeholder=\"+1 800 000 0000\" required>\n        <span class=\"field-error\" id=\"err_customer_service_telephone_number\"></span>\n      </div>\n\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label for=\"business_organized\">Legal Structure <span class=\"required\">*</span></label>\n          <select id=\"business_organized\" name=\"business_organized\" required>\n            <option value=\"\">Select\u2026</option>\n            <option value=\"Corporation\">Corporation</option>\n            <option value=\"LLC\">LLC</option>\n            <option value=\"Partnership\">Partnership</option>\n            <option value=\"Government\">Government</option>\n            <option value=\"Sole-Proprietorship\">Sole Proprietorship</option>\n            <option value=\"Non-Profit\">Non-Profit</option>\n            <option value=\"Other\">Other</option>\n          </select>\n          <span class=\"field-error\" id=\"err_business_organized\"></span>\n        </div>\n        <div class=\"form-group\">\n          <label for=\"business_location\">Company Location Type <span class=\"required\">*</span></label>\n          <select id=\"business_location\" name=\"business_location\" required>\n            <option value=\"\">Select\u2026</option>\n            <option value=\"Home-Based\">Home Based</option>\n            <option value=\"Co-Working\">Co-Working</option>\n            <option value=\"Corporate-Office\">Corporate Office</option>\n            <option value=\"Storefront\">Storefront</option>\n            <option value=\"Others\">Others</option>\n          </select>\n          <span class=\"field-error\" id=\"err_business_location\"></span>\n        </div>\n      </div>\n\n      <div class=\"form-group\">\n        <label for=\"business_formed\">Company Formation Date <span class=\"required\">*</span></label>\n        <input id=\"business_formed\" name=\"business_formed\" type=\"date\" required>\n        <span class=\"field-error\" id=\"err_business_formed\"></span>\n      </div>\n\n      <div class=\"form-group\" id=\"federal_tax_id_group\">\n        <label for=\"federal_tax_id\" id=\"federal_tax_id_label\">Federal Tax ID <span class=\"required\">*</span> <span class=\"hint\" id=\"federal_tax_id_hint\"></span></label>\n        <input id=\"federal_tax_id\" name=\"federal_tax_id\" type=\"text\" inputmode=\"numeric\" maxlength=\"11\" placeholder=\"XXX-XX-XXXX\" autocomplete=\"off\">\n        <span class=\"field-error\" id=\"err_federal_tax_id\"></span>\n      </div>\n\n      <div class=\"form-group\" id=\"business_register_number_group\" style=\"display:none\">\n        <label for=\"business_register_number\">Business Registration Number <span class=\"required\">*</span></label>\n        <input id=\"business_register_number\" name=\"business_register_number\" type=\"text\" maxlength=\"20\">\n        <span class=\"field-error\" id=\"err_business_register_number\"></span>\n      </div>\n\n      <div class=\"form-group\">\n        <label>Revenue Model <span class=\"required\">*</span></label>\n        <div class=\"checkbox-group\" id=\"marketing_model_group\">\n          <div class=\"checkbox-item\">\n            <input type=\"checkbox\" id=\"mm1\" name=\"marketingModel[]\" value=\"1\">\n            <label for=\"mm1\">One Time Purchase</label>\n          </div>\n          <div class=\"checkbox-item\">\n            <input type=\"checkbox\" id=\"mm2\" name=\"marketingModel[]\" value=\"2\">\n            <label for=\"mm2\">Recurring / Continuity / Subscription</label>\n          </div>\n          <div class=\"checkbox-item\">\n            <input type=\"checkbox\" id=\"mm3\" name=\"marketingModel[]\" value=\"3\">\n            <label for=\"mm3\">Trial Offer + Subscription</label>\n          </div>\n        </div>\n        <span class=\"field-error\" id=\"err_marketingModel\"></span>\n      </div>\n\n      <div class=\"form-group\" id=\"subscription_frequency_group\" style=\"display:none\">\n        <label for=\"subscription_frequency\">Subscription Frequency <span class=\"required\">*</span></label>\n        <select id=\"subscription_frequency\" name=\"subscription_frequency\">\n          <option value=\"\">Select\u2026</option>\n          <option value=\"1\">Monthly</option>\n          <option value=\"2\">Yearly</option>\n          <option value=\"3\">Other</option>\n        </select>\n        <span class=\"field-error\" id=\"err_subscription_frequency\"></span>\n      </div>\n\n      <div class=\"form-group\" id=\"subscription_frequency_other_group\" style=\"display:none\">\n        <label for=\"subscription_frequency_other\">Describe frequency <span class=\"required\">*</span></label>\n        <input id=\"subscription_frequency_other\" name=\"subscription_frequency_other\" type=\"text\" maxlength=\"255\" minlength=\"5\" placeholder=\"e.g. Quarterly\">\n        <span class=\"field-error\" id=\"err_subscription_frequency_other\"></span>\n      </div>\n\n      <!-- Legal Address -->\n      <div class=\"form-section\">\n        <h3>Legal Address</h3>\n        <div class=\"form-row\">\n          <div class=\"form-group\">\n            <label for=\"street_number\">Street Number <span class=\"required\">*</span></label>\n            <input id=\"street_number\" name=\"street_number\" type=\"text\" maxlength=\"10\" required placeholder=\"123\">\n            <span class=\"field-error\" id=\"err_street_number\"></span>\n          </div>\n          <div class=\"form-group\">\n            <label for=\"street_address\">Street Name <span class=\"required\">*</span></label>\n            <input id=\"street_address\" name=\"street_address\" type=\"text\" maxlength=\"255\" required placeholder=\"Main St\">\n            <span class=\"field-error\" id=\"err_street_address\"></span>\n          </div>\n        </div>\n        <div class=\"form-row\">\n          <div class=\"form-group\">\n            <label for=\"city\">City <span class=\"required\">*</span></label>\n            <input id=\"city\" name=\"city\" type=\"text\" maxlength=\"100\" required>\n            <span class=\"field-error\" id=\"err_city\"></span>\n          </div>\n          <div class=\"form-group\">\n            <label for=\"state\">State / Province <span class=\"required\">*</span></label>\n            <input id=\"state\" name=\"state\" type=\"text\" maxlength=\"100\" required>\n            <span class=\"field-error\" id=\"err_state\"></span>\n          </div>\n        </div>\n        <div class=\"form-row\">\n          <div class=\"form-group\">\n            <label for=\"postal_code\">Postal Code <span class=\"required\">*</span></label>\n            <input id=\"postal_code\" name=\"postal_code\" type=\"text\" maxlength=\"20\" required>\n            <span class=\"field-error\" id=\"err_postal_code\"></span>\n          </div>\n          <div class=\"form-group\">\n            <label for=\"address_country\">Country <span class=\"required\">*</span></label>\n            <select id=\"address_country\" name=\"address_country\" required>\n              <option value=\"\">Select\u2026</option>\n            </select>\n            <span class=\"field-error\" id=\"err_address_country\"></span>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"form-group\">\n        <label>Is your physical address the same as your legal address? <span class=\"required\">*</span></label>\n        <div class=\"radio-group\">\n          <div class=\"radio-item\"><input type=\"radio\" id=\"phys_same\" name=\"is_physical_address_same_as_legal_address\" value=\"1\" checked><label for=\"phys_same\">Yes</label></div>\n          <div class=\"radio-item\"><input type=\"radio\" id=\"phys_diff\" name=\"is_physical_address_same_as_legal_address\" value=\"0\"><label for=\"phys_diff\">No \u2014 enter separate address</label></div>\n        </div>\n      </div>\n\n      <!-- Physical Address (shown only when different) -->\n      <div id=\"physical_address_section\" style=\"display:none\">\n        <div class=\"form-section\">\n          <h3>Physical Address</h3>\n          <div class=\"form-row\">\n            <div class=\"form-group\">\n              <label for=\"physical_address_street_number\">Street Number <span class=\"required\">*</span></label>\n              <input id=\"physical_address_street_number\" name=\"physical_address_street_number\" type=\"text\" maxlength=\"10\">\n              <span class=\"field-error\" id=\"err_physical_address_street_number\"></span>\n            </div>\n            <div class=\"form-group\">\n              <label for=\"physical_address_street_address\">Street Name <span class=\"required\">*</span></label>\n              <input id=\"physical_address_street_address\" name=\"physical_address_street_address\" type=\"text\" maxlength=\"255\">\n              <span class=\"field-error\" id=\"err_physical_address_street_address\"></span>\n            </div>\n          </div>\n          <div class=\"form-row\">\n            <div class=\"form-group\">\n              <label for=\"physical_address_city\">City <span class=\"required\">*</span></label>\n              <input id=\"physical_address_city\" name=\"physical_address_city\" type=\"text\" maxlength=\"100\">\n              <span class=\"field-error\" id=\"err_physical_address_city\"></span>\n            </div>\n            <div class=\"form-group\">\n              <label for=\"physical_address_state\">State / Province <span class=\"required\">*</span></label>\n              <input id=\"physical_address_state\" name=\"physical_address_state\" type=\"text\" maxlength=\"100\">\n              <span class=\"field-error\" id=\"err_physical_address_state\"></span>\n            </div>\n          </div>\n          <div class=\"form-row\">\n            <div class=\"form-group\">\n              <label for=\"physical_address_postal_code\">Postal Code <span class=\"required\">*</span></label>\n              <input id=\"physical_address_postal_code\" name=\"physical_address_postal_code\" type=\"text\" maxlength=\"20\">\n              <span class=\"field-error\" id=\"err_physical_address_postal_code\"></span>\n            </div>\n            <div class=\"form-group\">\n              <label for=\"physical_address_country\">Country <span class=\"required\">*</span></label>\n              <select id=\"physical_address_country\" name=\"physical_address_country\">\n                <option value=\"\">Select\u2026</option>\n              </select>\n              <span class=\"field-error\" id=\"err_physical_address_country\"></span>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"btn-row\">\n        <button type=\"submit\" id=\"btn-step2\">Continue \u2014 Products \u2192</button>\n      </div>\n    </form>\n\n    <!-- \u2500\u2500 Step 3: Product & Processing \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n    <form id=\"form-step3\" class=\"step-section\" novalidate>\n      <h2>Product &amp; Processing</h2>\n      <p class=\"step-subtitle\">How you sell and deliver your products or services.</p>\n\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label for=\"fulfillment_by\">Fulfillment Method <span class=\"required\">*</span></label>\n          <select id=\"fulfillment_by\" name=\"fulfillment_by\" required>\n            <option value=\"\">Select\u2026</option>\n            <option value=\"Direct-By-You\">Direct By You</option>\n            <option value=\"Vendor\">Vendor</option>\n            <option value=\"Others\">Others</option>\n          </select>\n          <span class=\"field-error\" id=\"err_fulfillment_by\"></span>\n        </div>\n        <div class=\"form-group\">\n          <label for=\"customer_service_time\">Fulfillment Timeframe <span class=\"required\">*</span></label>\n          <select id=\"customer_service_time\" name=\"customer_service_time\" required>\n            <option value=\"\">Select\u2026</option>\n            <option value=\"0-7-days\">0\u20137 days</option>\n            <option value=\"7-30-days\">7\u201330 days</option>\n            <option value=\"31+days\">31+ days</option>\n          </select>\n          <span class=\"field-error\" id=\"err_customer_service_time\"></span>\n        </div>\n      </div>\n\n      <div class=\"form-group\" id=\"fullfillment_company_group\" style=\"display:none\">\n        <label for=\"fullfillment_company\">Fulfillment Vendor Name <span class=\"required\">*</span></label>\n        <input id=\"fullfillment_company\" name=\"fullfillment_company\" type=\"text\" maxlength=\"300\" placeholder=\"Vendor company name\">\n        <span class=\"field-error\" id=\"err_fullfillment_company\"></span>\n      </div>\n\n      <div class=\"form-group\">\n        <label for=\"refund_policy\">Refund Policy <span class=\"required\">*</span></label>\n        <select id=\"refund_policy\" name=\"refund_policy\" required>\n          <option value=\"\">Select\u2026</option>\n          <option value=\"Full-Refund\">Full Refund</option>\n          <option value=\"No-Refund\">No Refund</option>\n          <option value=\"Exchange-Only\">Exchange Only</option>\n          <option value=\"Partial-Refund\">Partial Refund</option>\n        </select>\n        <span class=\"field-error\" id=\"err_refund_policy\"></span>\n      </div>\n\n      <div class=\"form-group\">\n        <label for=\"shopping_cart\">Shopping Cart / CRM <span class=\"required\">*</span></label>\n        <select id=\"shopping_cart\" name=\"shopping_cart\" required>\n          <option value=\"\">Loading\u2026</option>\n        </select>\n        <span class=\"field-error\" id=\"err_shopping_cart\"></span>\n      </div>\n\n      <div class=\"form-group\" id=\"shopping_cart_other_group\" style=\"display:none\">\n        <label for=\"shopping_cart_other\">Other Sales Platform <span class=\"required\">*</span></label>\n        <input id=\"shopping_cart_other\" name=\"shopping_cart_other\" type=\"text\" maxlength=\"255\" placeholder=\"Instagram DMs, Custom CRM, etc.\">\n        <span class=\"field-error\" id=\"err_shopping_cart_other\"></span>\n      </div>\n\n      <div class=\"form-group\">\n        <label for=\"leave_deposit\">Are customers required to pay a deposit? <span class=\"required\">*</span></label>\n        <select id=\"leave_deposit\" name=\"leave_deposit\" required>\n          <option value=\"\">Select\u2026</option>\n          <option value=\"1\">Yes</option>\n          <option value=\"0\">No</option>\n        </select>\n        <span class=\"field-error\" id=\"err_leave_deposit\"></span>\n      </div>\n\n      <div class=\"form-section\">\n        <h3>Transaction Entry Methods <span class=\"hint\" style=\"text-transform:none;font-size:.8rem;color:#6b7280\">(must total 100%)</span></h3>\n        <div class=\"pct-sliders\">\n          <div class=\"pct-slider-row\">\n            <label for=\"card_swiped\">Card Presented</label>\n            <input id=\"card_swiped\" name=\"card_swiped\" type=\"range\" min=\"0\" max=\"100\" step=\"5\" value=\"40\" required>\n            <span class=\"pct-val\" id=\"val_card_swiped\">40%</span>\n          </div>\n          <div class=\"pct-slider-row\">\n            <label for=\"customer_entered\">Customer Keyed-In</label>\n            <input id=\"customer_entered\" name=\"customer_entered\" type=\"range\" min=\"0\" max=\"100\" step=\"5\" value=\"30\" required>\n            <span class=\"pct-val\" id=\"val_customer_entered\">30%</span>\n          </div>\n          <div class=\"pct-slider-row\">\n            <label for=\"staff_entered\">Staff Keyed-In</label>\n            <input id=\"staff_entered\" name=\"staff_entered\" type=\"range\" min=\"0\" max=\"100\" step=\"5\" value=\"30\" required>\n            <span class=\"pct-val\" id=\"val_staff_entered\">30%</span>\n          </div>\n        </div>\n        <p class=\"pct-sum-note\" id=\"pct_sum_note\">Total: <strong id=\"pct_total\">100</strong>%</p>\n        <span class=\"field-error\" id=\"err_card_swiped\"></span>\n      </div>\n\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label for=\"average_transaction_amount\">Avg. Transaction (USD) <span class=\"required\">*</span></label>\n          <input id=\"average_transaction_amount\" name=\"average_transaction_amount\" type=\"number\" min=\"1\" required placeholder=\"200\">\n          <span class=\"field-error\" id=\"err_average_transaction_amount\"></span>\n        </div>\n        <div class=\"form-group\">\n          <label for=\"highest_transaction_amount\">Highest Transaction (USD) <span class=\"required\">*</span></label>\n          <input id=\"highest_transaction_amount\" name=\"highest_transaction_amount\" type=\"number\" min=\"1\" required placeholder=\"1000\">\n          <span class=\"field-error\" id=\"err_highest_transaction_amount\"></span>\n        </div>\n      </div>\n\n      <div class=\"form-group\">\n        <label for=\"describe_services\">Describe Your Products / Services <span class=\"required\">*</span></label>\n        <textarea id=\"describe_services\" name=\"describe_services\" required placeholder=\"Briefly describe your primary products or services\"></textarea>\n        <span class=\"field-error\" id=\"err_describe_services\"></span>\n      </div>\n\n      <div class=\"form-group\">\n        <label for=\"describe_highest_transaction\">Describe Your Highest-Value Transaction <span class=\"required\">*</span></label>\n        <textarea id=\"describe_highest_transaction\" name=\"describe_highest_transaction\" minlength=\"15\" required placeholder=\"Describe the product or service behind your largest single transaction\"></textarea>\n        <span class=\"field-error\" id=\"err_describe_highest_transaction\"></span>\n      </div>\n\n      <div class=\"btn-row\">\n        <button type=\"submit\" id=\"btn-step3\">Continue \u2014 Owners \u2192</button>\n      </div>\n    </form>\n\n    <!-- \u2500\u2500 Step 4: Owners \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n    <form id=\"form-step4\" class=\"step-section\" novalidate>\n      <h2>Business Owners</h2>\n      <p class=\"step-subtitle\">Identity information for the primary owner. If the applicant owns &lt;51%, a second owner is required.</p>\n\n      <div class=\"form-group\">\n        <label>Are you the business owner / primary contact? <span class=\"required\">*</span></label>\n        <div class=\"radio-group\">\n          <div class=\"radio-item\"><input type=\"radio\" id=\"pc_yes\" name=\"primary_contact\" value=\"1\" checked><label for=\"pc_yes\">Yes, I am</label></div>\n          <div class=\"radio-item\"><input type=\"radio\" id=\"pc_no\" name=\"primary_contact\" value=\"0\"><label for=\"pc_no\">No \u2014 I'm a representative</label></div>\n        </div>\n      </div>\n\n      <div class=\"form-group\" id=\"primary_contact_job_title_group\" style=\"display:none\">\n        <label for=\"primary_contact_job_title\">Your Job Title <span class=\"required\">*</span></label>\n        <input id=\"primary_contact_job_title\" name=\"primary_contact_job_title\" type=\"text\" maxlength=\"100\" placeholder=\"e.g. Operations Manager\">\n        <span class=\"field-error\" id=\"err_primary_contact_job_title\"></span>\n      </div>\n\n      <!-- Owner 1 -->\n      <div class=\"form-section\">\n        <h3>Owner 1</h3>\n\n        <div id=\"owner1_name_group\" style=\"display:none\">\n          <div class=\"form-row\">\n            <div class=\"form-group\">\n              <label for=\"first_name_1\">First Name <span class=\"required\">*</span></label>\n              <input id=\"first_name_1\" name=\"first_name.1\" type=\"text\" maxlength=\"60\">\n              <span class=\"field-error\" id=\"err_first_name_1\"></span>\n            </div>\n            <div class=\"form-group\">\n              <label for=\"last_name_1\">Last Name <span class=\"required\">*</span></label>\n              <input id=\"last_name_1\" name=\"last_name.1\" type=\"text\" maxlength=\"60\">\n              <span class=\"field-error\" id=\"err_last_name_1\"></span>\n            </div>\n          </div>\n          <div class=\"form-group\">\n            <label for=\"email_1\">Email <span class=\"required\">*</span></label>\n            <input id=\"email_1\" name=\"email.1\" type=\"email\">\n            <span class=\"field-error\" id=\"err_email_1\"></span>\n          </div>\n        </div>\n\n        <div class=\"form-row\">\n          <div class=\"form-group\">\n            <label for=\"phone_1\">Phone <span class=\"required\">*</span></label>\n            <input id=\"phone_1\" name=\"phone.1\" type=\"tel\" maxlength=\"20\" placeholder=\"+1 202 555 1234\">\n            <span class=\"field-error\" id=\"err_phone_1\"></span>\n          </div>\n          <div class=\"form-group\">\n            <label for=\"title_1\">Job Title <span class=\"required\">*</span></label>\n            <select id=\"title_1\" name=\"title.1\" required>\n              <option value=\"\">Select\u2026</option>\n              <option value=\"ceo\">CEO</option>\n              <option value=\"cfo\">CFO</option>\n              <option value=\"chairman\">Chairman</option>\n              <option value=\"co-owner\">Co-owner</option>\n              <option value=\"controller\">Controller</option>\n              <option value=\"director\">Director</option>\n              <option value=\"general-manager\">General Manager</option>\n              <option value=\"office-manager\">Office Manager</option>\n              <option value=\"owner\">Owner</option>\n              <option value=\"partner\">Partner</option>\n              <option value=\"president\">President</option>\n              <option value=\"treasurer\">Treasurer</option>\n              <option value=\"vice-president\">Vice President</option>\n              <option value=\"other\">Other</option>\n            </select>\n            <span class=\"field-error\" id=\"err_title_1\"></span>\n          </div>\n        </div>\n\n        <div class=\"form-row\">\n          <div class=\"form-group\">\n            <label id=\"ssn_1_label\" for=\"ssn_1\">SSN / Tax ID <span class=\"required\">*</span></label>\n            <input id=\"ssn_1\" name=\"ssn.1\" type=\"text\" maxlength=\"20\" autocomplete=\"off\" placeholder=\"XXX-XX-XXXX\">\n            <span class=\"sensitive-note\" id=\"ssn_1_hint\">US/CA/PR: enter 9 digits as XXX-XX-XXXX</span>\n            <span class=\"field-error\" id=\"err_ssn_1\"></span>\n          </div>\n          <div class=\"form-group\">\n            <label for=\"dob_1\">Date of Birth <span class=\"required\">*</span></label>\n            <input id=\"dob_1\" name=\"dob.1\" type=\"date\" required>\n            <span class=\"sensitive-note\">Must be 18\u2013100 years old</span>\n            <span class=\"field-error\" id=\"err_dob_1\"></span>\n          </div>\n        </div>\n\n        <div class=\"form-group\">\n          <label for=\"ownership_percentage_1\">Ownership % <span class=\"required\">*</span></label>\n          <input id=\"ownership_percentage_1\" name=\"ownership_percentage.1\" type=\"number\" min=\"1\" max=\"100\" step=\"1\" required placeholder=\"e.g. 51\">\n          <span class=\"field-error\" id=\"err_ownership_percentage_1\"></span>\n        </div>\n\n        <!-- Owner 1 Home Address -->\n        <div class=\"form-row\">\n          <div class=\"form-group\">\n            <label for=\"street_number_1\">Street Number <span class=\"required\">*</span></label>\n            <input id=\"street_number_1\" name=\"street_number.1\" type=\"text\" maxlength=\"10\" required>\n            <span class=\"field-error\" id=\"err_street_number_1\"></span>\n          </div>\n          <div class=\"form-group\">\n            <label for=\"street_address_1\">Street Name <span class=\"required\">*</span></label>\n            <input id=\"street_address_1\" name=\"street_address.1\" type=\"text\" maxlength=\"255\" required>\n            <span class=\"field-error\" id=\"err_street_address_1\"></span>\n          </div>\n        </div>\n        <div class=\"form-row\">\n          <div class=\"form-group\">\n            <label for=\"city_1\">City <span class=\"required\">*</span></label>\n            <input id=\"city_1\" name=\"city.1\" type=\"text\" maxlength=\"100\" required>\n          </div>\n          <div class=\"form-group\">\n            <label for=\"state_1\">State / Province <span class=\"required\">*</span></label>\n            <input id=\"state_1\" name=\"state.1\" type=\"text\" required>\n          </div>\n        </div>\n        <div class=\"form-row\">\n          <div class=\"form-group\">\n            <label for=\"postal_code_1\">Postal Code <span class=\"required\">*</span></label>\n            <input id=\"postal_code_1\" name=\"postal_code.1\" type=\"text\" maxlength=\"20\" required>\n          </div>\n          <div class=\"form-group\">\n            <label for=\"country_1\">Country <span class=\"required\">*</span></label>\n            <select id=\"country_1\" name=\"country.1\" required>\n              <option value=\"\">Select\u2026</option>\n            </select>\n            <span class=\"field-error\" id=\"err_country_1\"></span>\n          </div>\n        </div>\n\n        <div class=\"form-row\">\n          <div class=\"form-group\">\n            <label for=\"license_1\">Driver License # <span class=\"required\">*</span></label>\n            <input id=\"license_1\" name=\"license.1\" type=\"text\" minlength=\"5\" maxlength=\"25\" autocomplete=\"off\" required>\n            <span class=\"field-error\" id=\"err_license_1\"></span>\n          </div>\n          <div class=\"form-group\" id=\"dl_state_1_group\" style=\"display:none\">\n            <label for=\"driver_license_state_1\">License State <span class=\"required\">*</span></label>\n            <select id=\"driver_license_state_1\" name=\"driver_license_state.1\">\n              <option value=\"\">Select\u2026</option>\n            </select>\n            <span class=\"field-error\" id=\"err_driver_license_state_1\"></span>\n          </div>\n        </div>\n\n        <div class=\"form-group\" id=\"dl_expiry_1_group\" style=\"display:none\">\n          <label for=\"driver_license_expiration_date_1\">License Expiration Date <span class=\"required\">*</span></label>\n          <input id=\"driver_license_expiration_date_1\" name=\"driver_license_expiration_date.1\" type=\"date\" autocomplete=\"off\">\n          <span class=\"sensitive-note\">Must be today or a future date</span>\n          <span class=\"field-error\" id=\"err_driver_license_expiration_date_1\"></span>\n        </div>\n\n        <div class=\"form-group\">\n          <label>Has a bankruptcy been filed? <span class=\"required\">*</span></label>\n          <div class=\"radio-group\">\n            <div class=\"radio-item\"><input type=\"radio\" id=\"bk1_no\" name=\"bankruptcy_filed.1\" value=\"0\" checked><label for=\"bk1_no\">No</label></div>\n            <div class=\"radio-item\"><input type=\"radio\" id=\"bk1_yes\" name=\"bankruptcy_filed.1\" value=\"1\"><label for=\"bk1_yes\">Yes</label></div>\n          </div>\n        </div>\n\n        <div id=\"bankruptcy1_details\" style=\"display:none\">\n          <div class=\"form-group\">\n            <label>Was the bankruptcy discharged? <span class=\"required\">*</span></label>\n            <div class=\"radio-group\">\n              <div class=\"radio-item\"><input type=\"radio\" id=\"bkd1_no\" name=\"bankruptcy_discharged.1\" value=\"0\"><label for=\"bkd1_no\">No</label></div>\n              <div class=\"radio-item\"><input type=\"radio\" id=\"bkd1_yes\" name=\"bankruptcy_discharged.1\" value=\"1\"><label for=\"bkd1_yes\">Yes</label></div>\n            </div>\n            <span class=\"field-error\" id=\"err_bankruptcy_discharged_1\"></span>\n          </div>\n          <div class=\"form-group\" id=\"bkd_date_1_group\" style=\"display:none\">\n            <label for=\"bankruptcy_discharged_date_1\">Discharge Date <span class=\"required\">*</span></label>\n            <input id=\"bankruptcy_discharged_date_1\" name=\"bankruptcy_discharged_date.1\" type=\"date\">\n            <span class=\"sensitive-note\">Must be today or a past date</span>\n            <span class=\"field-error\" id=\"err_bankruptcy_discharged_date_1\"></span>\n          </div>\n        </div>\n      </div>\n\n      <!-- Owner 2 (shown when ownership_percentage.1 < 51) -->\n      <div id=\"owner2_section\" style=\"display:none\">\n        <div class=\"form-section\">\n          <h3>Owner 2 <span class=\"hint\" style=\"text-transform:none;font-size:.8rem\">(required when Owner 1 owns less than 51%)</span></h3>\n\n          <div class=\"form-row\">\n            <div class=\"form-group\">\n              <label for=\"first_name_2\">First Name <span class=\"required\">*</span></label>\n              <input id=\"first_name_2\" name=\"first_name.2\" type=\"text\" maxlength=\"60\">\n              <span class=\"field-error\" id=\"err_first_name_2\"></span>\n            </div>\n            <div class=\"form-group\">\n              <label for=\"last_name_2\">Last Name <span class=\"required\">*</span></label>\n              <input id=\"last_name_2\" name=\"last_name.2\" type=\"text\" maxlength=\"60\">\n              <span class=\"field-error\" id=\"err_last_name_2\"></span>\n            </div>\n          </div>\n          <div class=\"form-group\">\n            <label for=\"email_2\">Email <span class=\"required\">*</span></label>\n            <input id=\"email_2\" name=\"email.2\" type=\"email\">\n            <span class=\"field-error\" id=\"err_email_2\"></span>\n          </div>\n          <div class=\"form-row\">\n            <div class=\"form-group\">\n              <label for=\"phone_2\">Phone <span class=\"required\">*</span></label>\n              <input id=\"phone_2\" name=\"phone.2\" type=\"tel\" maxlength=\"20\" placeholder=\"+1 202 555 1234\">\n              <span class=\"field-error\" id=\"err_phone_2\"></span>\n            </div>\n            <div class=\"form-group\">\n              <label for=\"title_2\">Job Title <span class=\"required\">*</span></label>\n              <select id=\"title_2\" name=\"title.2\">\n                <option value=\"\">Select\u2026</option>\n                <option value=\"ceo\">CEO</option><option value=\"cfo\">CFO</option>\n                <option value=\"chairman\">Chairman</option><option value=\"co-owner\">Co-owner</option>\n                <option value=\"controller\">Controller</option><option value=\"director\">Director</option>\n                <option value=\"general-manager\">General Manager</option><option value=\"office-manager\">Office Manager</option>\n                <option value=\"owner\">Owner</option><option value=\"partner\">Partner</option>\n                <option value=\"president\">President</option><option value=\"treasurer\">Treasurer</option>\n                <option value=\"vice-president\">Vice President</option><option value=\"other\">Other</option>\n              </select>\n              <span class=\"field-error\" id=\"err_title_2\"></span>\n            </div>\n          </div>\n          <div class=\"form-row\">\n            <div class=\"form-group\">\n              <label id=\"ssn_2_label\" for=\"ssn_2\">SSN / Tax ID <span class=\"required\">*</span></label>\n              <input id=\"ssn_2\" name=\"ssn.2\" type=\"text\" maxlength=\"20\" autocomplete=\"off\" placeholder=\"XXX-XX-XXXX\">\n              <span class=\"field-error\" id=\"err_ssn_2\"></span>\n            </div>\n            <div class=\"form-group\">\n              <label for=\"dob_2\">Date of Birth <span class=\"required\">*</span></label>\n              <input id=\"dob_2\" name=\"dob.2\" type=\"date\">\n              <span class=\"sensitive-note\">Must be 18\u2013100 years old</span>\n              <span class=\"field-error\" id=\"err_dob_2\"></span>\n            </div>\n          </div>\n          <div class=\"form-group\">\n            <label for=\"ownership_percentage_2\">Ownership % <span class=\"required\">*</span></label>\n            <input id=\"ownership_percentage_2\" name=\"ownership_percentage.2\" type=\"number\" min=\"1\" max=\"100\" step=\"1\" placeholder=\"e.g. 49\">\n            <span class=\"field-error\" id=\"err_ownership_percentage_2\"></span>\n          </div>\n\n          <div class=\"form-row\">\n            <div class=\"form-group\">\n              <label for=\"street_number_2\">Street Number <span class=\"required\">*</span></label>\n              <input id=\"street_number_2\" name=\"street_number.2\" type=\"text\" maxlength=\"10\">\n            </div>\n            <div class=\"form-group\">\n              <label for=\"street_address_2\">Street Name <span class=\"required\">*</span></label>\n              <input id=\"street_address_2\" name=\"street_address.2\" type=\"text\" maxlength=\"255\">\n            </div>\n          </div>\n          <div class=\"form-row\">\n            <div class=\"form-group\">\n              <label for=\"city_2\">City <span class=\"required\">*</span></label>\n              <input id=\"city_2\" name=\"city.2\" type=\"text\" maxlength=\"100\">\n            </div>\n            <div class=\"form-group\">\n              <label for=\"state_2\">State / Province <span class=\"required\">*</span></label>\n              <input id=\"state_2\" name=\"state.2\" type=\"text\">\n            </div>\n          </div>\n          <div class=\"form-row\">\n            <div class=\"form-group\">\n              <label for=\"postal_code_2\">Postal Code <span class=\"required\">*</span></label>\n              <input id=\"postal_code_2\" name=\"postal_code.2\" type=\"text\" maxlength=\"20\">\n            </div>\n            <div class=\"form-group\">\n              <label for=\"country_2\">Country <span class=\"required\">*</span></label>\n              <select id=\"country_2\" name=\"country.2\">\n                <option value=\"\">Select\u2026</option>\n              </select>\n              <span class=\"field-error\" id=\"err_country_2\"></span>\n            </div>\n          </div>\n\n          <div class=\"form-row\">\n            <div class=\"form-group\">\n              <label for=\"license_2\">Driver License # <span class=\"required\">*</span></label>\n              <input id=\"license_2\" name=\"license.2\" type=\"text\" minlength=\"5\" maxlength=\"25\" autocomplete=\"off\">\n              <span class=\"field-error\" id=\"err_license_2\"></span>\n            </div>\n            <div class=\"form-group\" id=\"dl_state_2_group\" style=\"display:none\">\n              <label for=\"driver_license_state_2\">License State <span class=\"required\">*</span></label>\n              <select id=\"driver_license_state_2\" name=\"driver_license_state.2\">\n                <option value=\"\">Select\u2026</option>\n              </select>\n              <span class=\"field-error\" id=\"err_driver_license_state_2\"></span>\n            </div>\n          </div>\n          <div class=\"form-group\" id=\"dl_expiry_2_group\" style=\"display:none\">\n            <label for=\"driver_license_expiration_date_2\">License Expiration Date <span class=\"required\">*</span></label>\n            <input id=\"driver_license_expiration_date_2\" name=\"driver_license_expiration_date.2\" type=\"date\" autocomplete=\"off\">\n            <span class=\"sensitive-note\">Must be today or a future date</span>\n            <span class=\"field-error\" id=\"err_driver_license_expiration_date_2\"></span>\n          </div>\n\n          <div class=\"form-group\">\n            <label>Has a bankruptcy been filed? <span class=\"required\">*</span></label>\n            <div class=\"radio-group\">\n              <div class=\"radio-item\"><input type=\"radio\" id=\"bk2_no\" name=\"bankruptcy_filed.2\" value=\"0\" checked><label for=\"bk2_no\">No</label></div>\n              <div class=\"radio-item\"><input type=\"radio\" id=\"bk2_yes\" name=\"bankruptcy_filed.2\" value=\"1\"><label for=\"bk2_yes\">Yes</label></div>\n            </div>\n          </div>\n          <div id=\"bankruptcy2_details\" style=\"display:none\">\n            <div class=\"form-group\">\n              <label>Was the bankruptcy discharged?</label>\n              <div class=\"radio-group\">\n                <div class=\"radio-item\"><input type=\"radio\" id=\"bkd2_no\" name=\"bankruptcy_discharged.2\" value=\"0\"><label for=\"bkd2_no\">No</label></div>\n                <div class=\"radio-item\"><input type=\"radio\" id=\"bkd2_yes\" name=\"bankruptcy_discharged.2\" value=\"1\"><label for=\"bkd2_yes\">Yes</label></div>\n              </div>\n              <span class=\"field-error\" id=\"err_bankruptcy_discharged_2\"></span>\n            </div>\n            <div class=\"form-group\" id=\"bkd_date_2_group\" style=\"display:none\">\n              <label for=\"bankruptcy_discharged_date_2\">Discharge Date</label>\n              <input id=\"bankruptcy_discharged_date_2\" name=\"bankruptcy_discharged_date.2\" type=\"date\">\n              <span class=\"sensitive-note\">Must be today or a past date</span>\n              <span class=\"field-error\" id=\"err_bankruptcy_discharged_date_2\"></span>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"btn-row\">\n        <button type=\"submit\" id=\"btn-step4\">Continue \u2014 Banking \u2192</button>\n      </div>\n    </form>\n\n    <!-- \u2500\u2500 Step 5: Banking \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n    <form id=\"form-step5\" class=\"step-section\" novalidate>\n      <h2>Banking</h2>\n      <p class=\"step-subtitle\">Bank account for deposits and current processor info.</p>\n\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label id=\"routing_number_label\" for=\"routing_number\">Routing Number <span class=\"required\">*</span></label>\n          <input id=\"routing_number\" name=\"routing_number\" type=\"text\" maxlength=\"20\" autocomplete=\"off\" required placeholder=\"Routing Number\">\n          <span class=\"sensitive-note\" id=\"routing_number_hint\">US: exactly 9 digits</span>\n          <span class=\"field-error\" id=\"err_routing_number\"></span>\n        </div>\n        <div class=\"form-group\">\n          <label id=\"account_number_label\" for=\"account_number\">Account Number <span class=\"required\">*</span></label>\n          <input id=\"account_number\" name=\"account_number\" type=\"text\" maxlength=\"20\" autocomplete=\"off\" required>\n          <span class=\"sensitive-note\" id=\"account_number_hint\">US: 8\u201317 digits</span>\n          <span class=\"field-error\" id=\"err_account_number\"></span>\n        </div>\n      </div>\n\n      <!-- Canada-specific fields -->\n      <div id=\"ca_banking_fields\" style=\"display:none\">\n        <div class=\"form-row\">\n          <div class=\"form-group\">\n            <label for=\"institution_number\">Institution Number <span class=\"required\">*</span></label>\n            <input id=\"institution_number\" name=\"institution_number\" type=\"text\" maxlength=\"3\" pattern=\"[0-9]{3}\" placeholder=\"3 digits\">\n            <span class=\"field-error\" id=\"err_institution_number\"></span>\n          </div>\n          <div class=\"form-group\">\n            <label for=\"customer_pay_currency\">Customer Pays In <span class=\"required\">*</span></label>\n            <div class=\"radio-group\" style=\"margin-top:10px\">\n              <div class=\"radio-item\"><input type=\"radio\" id=\"cur_usd\" name=\"customer_pay_currency\" value=\"USD\"><label for=\"cur_usd\">USD</label></div>\n              <div class=\"radio-item\"><input type=\"radio\" id=\"cur_cad\" name=\"customer_pay_currency\" value=\"CAD\"><label for=\"cur_cad\">CAD</label></div>\n            </div>\n            <span class=\"field-error\" id=\"err_customer_pay_currency\"></span>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"form-group\">\n        <label for=\"current_processing\">Are you currently processing credit cards? <span class=\"required\">*</span></label>\n        <select id=\"current_processing\" name=\"current_processing\" required>\n          <option value=\"\">Select\u2026</option>\n          <option value=\"1\">Yes</option>\n          <option value=\"0\">No</option>\n        </select>\n        <span class=\"field-error\" id=\"err_current_processing\"></span>\n      </div>\n\n      <div class=\"form-group\" id=\"processor_name_group\" style=\"display:none\">\n        <label for=\"processor_name\">Current Processor Name <span class=\"required\">*</span></label>\n        <input id=\"processor_name\" name=\"processor_name\" type=\"text\" maxlength=\"255\" placeholder=\"e.g. Stripe, Square\">\n        <span class=\"field-error\" id=\"err_processor_name\"></span>\n      </div>\n\n      <div class=\"btn-row\">\n        <button type=\"submit\" id=\"btn-step5\">Continue \u2014 Final Details \u2192</button>\n      </div>\n    </form>\n\n    <!-- \u2500\u2500 Step 6: Final Details \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n    <form id=\"form-step6\" class=\"step-section\" novalidate>\n      <h2>Final Details</h2>\n      <p class=\"step-subtitle\">Almost done \u2014 just a few last questions.</p>\n\n      <div class=\"form-group\">\n        <label for=\"howdidyouhear\">How did you find us? <span class=\"required\">*</span></label>\n        <select id=\"howdidyouhear\" name=\"howdidyouhear\" required>\n          <option value=\"\">Loading\u2026</option>\n        </select>\n        <span class=\"field-error\" id=\"err_howdidyouhear\"></span>\n      </div>\n\n      <div class=\"form-group\" id=\"hear_other_group\" style=\"display:none\">\n        <label for=\"hear_about_us_other\">Tell us more <span class=\"required\">*</span></label>\n        <input id=\"hear_about_us_other\" name=\"hear_about_us_other\" type=\"text\" maxlength=\"255\" placeholder=\"e.g. Friend's name or referral details\">\n        <span class=\"field-error\" id=\"err_hear_about_us_other\"></span>\n      </div>\n\n      <div class=\"form-group\">\n        <label for=\"multiple_merchant_accounts\">Do you need multiple merchant accounts? <span class=\"required\">*</span></label>\n        <select id=\"multiple_merchant_accounts\" name=\"multiple_merchant_accounts\" required>\n          <option value=\"\">Select\u2026</option>\n          <option value=\"1\">Yes</option>\n          <option value=\"0\">No</option>\n        </select>\n        <span class=\"field-error\" id=\"err_multiple_merchant_accounts\"></span>\n      </div>\n\n      <div class=\"form-group\">\n        <label for=\"transaction_device\">Transaction Device</label>\n        <select id=\"transaction_device\" name=\"transaction_device\">\n          <option value=\"\">Select\u2026</option>\n          <option value=\"Easy-Pay-Direct-Gateway\">Easy Pay Direct Gateway</option>\n          <option value=\"Another-Payment-Gateway\">Another Payment Gateway</option>\n          <option value=\"Need-terminal/POS-system\">Need Terminal / POS System</option>\n          <option value=\"Own-terminal/POS-system\">Own Terminal / POS System</option>\n          <option value=\"iPhone/Android\">iPhone / Android</option>\n          <option value=\"Other\">Other</option>\n        </select>\n      </div>\n\n      <div class=\"form-group\">\n        <label for=\"bad_experience\">Have you had a bad experience with a payment provider? <span class=\"required\">*</span></label>\n        <select id=\"bad_experience\" name=\"bad_experience\" required>\n          <option value=\"\">Select\u2026</option>\n          <option value=\"0\">No</option>\n          <option value=\"1\">Yes</option>\n        </select>\n        <span class=\"field-error\" id=\"err_bad_experience\"></span>\n      </div>\n\n      <div class=\"form-group\" id=\"bad_exp_detail_group\" style=\"display:none\">\n        <label for=\"bad_experience_happened\">Which provider? <span class=\"required\">*</span></label>\n        <input id=\"bad_experience_happened\" name=\"bad_experience_happened\" type=\"text\" maxlength=\"500\" placeholder=\"Provider name\">\n        <span class=\"field-error\" id=\"err_bad_experience_happened\"></span>\n      </div>\n\n      <div class=\"form-group\">\n        <label>What would help your company grow? <span class=\"hint\">(optional)</span></label>\n        <div class=\"checkbox-group\" id=\"interests_group\">\n          <span style=\"color:#9ca3af;font-size:.85rem\">Loading\u2026</span>\n        </div>\n      </div>\n\n      <div class=\"form-group\">\n        <label>Terms and Conditions <span class=\"required\">*</span></label>\n        <textarea class=\"terms-box\" readonly>TERMS AND CONDITIONS OF MERCHANT SERVICE AGREEMENT\n\n1. INTRODUCTION AND DEFINITIONS.\n\nThis document, \"Terms and Conditions of Merchant Service Agreement\" (\"Terms and Conditions\") accompanies the document \"Easy Pay Direct, it's affiliated banking or processing partners Payments Merchant Application\" (\"Merchant Application\"). The Merchant Service Agreement (\"Agreement\" or \"Card Services Agreement\") includes these Terms and Conditions and the terms and conditions of the Merchant Application. The Member bank identified in such Merchant Application (\"Member\") is a member of Visa USA, Inc.(\"Visa\") and MasterCard International, Inc.(\"MasterCard\"). Easy Pay Direct, it's affiliated banking or processing partners Payments Direct, Inc.(\"Easy Pay Direct, it's affiliated banking or processing partners\") is a registered independent sales organization of Visa, a member service provider of MasterCard and a registered acquirer for Discover Financial Services LLC (\"Discover\"). Merchant and Easy Pay Direct, it's affiliated banking or processing partners agree that the rights and obligations contained in these Terms and Conditions of Merchant Service Agreement do not apply to the Member with respect to Discover transactions and Switched Transactions (as defined below). To the extent Merchant accepts Discover cards, the provisions in this Agreement with respect to Discover apply if Merchant does not have a separate agreement with Discover. To the extent Merchant accepts Discover cards and has a separate agreement with Discover, Discover card transactions shall be processed as Switched Transactions (as defined below). Any references to the Debit Sponsor shall refer to the debit sponsor identified below. The Agreement is between Easy Pay Direct, it's affiliated banking or processing partners, the Member and the merchant identified in the Merchant Application (\"Merchant\"). Under the terms of the Agreement, Merchant will be furnished with the services and products described herein and in the Merchant Application, and selected by Merchant therein (collectively and individually, as applicable, the \"Services\"). Easy Pay Direct, its affiliated banking or processing partners will be the sole and exclusive provider of the Services to Merchant during the term of this Agreement. Any Merchant accepted by Easy Pay Direct, it's affiliated banking or processing partners for card processing services agrees to be bound by the Agreement, including the terms of the Merchant Application and these Terms And Conditions as may be modified or amended in the future. A Merchant's submission of a transaction to Easy Pay Direct, its affiliated banking or processing partners Shall be deemed to signify Merchant's acceptance of the Merchant Services Agreement, including the Terms and Conditions herein. Except as expressly stated in the first three paragraphs of Section 13, all terms and conditions of this Merchant Services Agreement shall survive termination to the extent necessary to protect Easy Pay Direct, it's affiliated banking or processing partners Direct or Member's and anyone acting on Easy Pay Direct, its affiliated banking or processing partners or Member's behalf's rights herein.\n\n\n2. SERVICE DESCRIPTIONS.\n\nCredit Card processing services: Easy Pay Direct, it's affiliated banking or processing partners's actions to the appropriate card associations and/or issuers (e.g., Visa, MasterCard, Diners, Discover); settlement; dispute resolution with cardholders' banks; and transaction-related reporting, statements and products.\n\nDebit/ATM Processing Services: Easy Pay Direct, it's affiliated banking or processing partners has connected to the following debit card networks (\"Networks\"): Accel, AFFN, Interlink, MAC, Maestro, NYCE, Pulse, Star, and Tyme. Easy Pay Direct, it's affiliated banking or processing partners will provide Merchant with the ability to access the Networks that Easy Pay Direct, it's affiliated banking or processing partners has connected to for the purpose of authorizing debit card transactions at the point of sale from cards issued by the members of the respective Networks. Easy Pay Direct, its affiliated banking or processing partners will provide connection to such Networks, terminal applications, settlement and reporting activities.\n\nEBT Transaction Processing Services: Easy Pay Direct, it's affiliated banking or processing partners offers electronic interfaces to Electronic Benefits Transfer (\"EBT\") networks for the processing of cash payments or credits to or for the benefit of benefit recipients (\"Recipients\"). Easy Pay Direct, it's affiliated banking or processing partners will provide settlement and switching services for various Point of Sale transactions initiated through Merchant for the authorization of the issuance of the United States Department of Agriculture, Food and Nutrition Services (\"FNS\") food stamp benefits (\"FS Benefits\") and/or government delivered cash assistance benefits (\"Cash Benefits,\" with FS Benefits, \"Benefits\") to Recipients through the use of a state-issued card (\"EBT Card\"). With respect to Visa and MasterCard products, Merchant agrees to pay and Merchant's account(s) will be charged pursuant to Section 5 of this Agreement for any additional fees incurred as a result of Merchant's subsequent acceptance of transactions with any Visa or MasterCard product that it has not elected to accept.\n\n\n3. PROCEDURES.\n\nMerchant will permit holders of valid cards bearing the symbols of the cards authorized to be accepted by Merchant hereunder to charge purchases or leases of goods and services and the debt resulting there from shall be purchased hereunder on a provisional basis in accordance with Section 5 below, provided that the transaction complies with the terms of this Agreement. All indebtedness submitted by Merchant for purchase will be evidenced by an approved sales slip. Merchant will not present for purchase any indebtedness that does not arise out of a transaction between a cardholder and Merchant. Merchant agrees to follow the Card Acceptance Guide which is incorporated into and made part of this Agreement, and to be bound by the operating regulations and rules of Visa, MasterCard, Discover and any other card association or network organization covered by this Agreement, as any of the above referenced documents may be modified and amended from time to time. Merchant acknowledges that the Card Acceptance Guide is located on Easy Pay Direct, it's affiliated banking or processing partners's website at www.easypaymentsinc.com. Without limiting the generality of the foregoing, Merchant agrees to comply with and be bound by, and to cause any third party who provides Merchant with services related to payment processing or facilitates Merchant's ability to accept credit and debit cards and who is not a party to this Card Services Agreement to comply with and be bound by the rules and regulations of Visa, MasterCard, Discover and any other card association or network organization related to cardholders and transaction information security, including without limitation, Payment Card Industry Data Security Standards (\"PCI DSS\"), Visa's Cardholder Information Security Program and MasterCard's Site Data Protection Program.\n\n\n4. MARKETING.\n\nMerchant shall adequately display the card issuer service marks and promotional materials supplied by Easy Pay Direct, it's affiliated banking or processing partners. Merchant shall cease to use or display such service marks immediately upon notice from Easy Pay Direct, it's affiliated banking or processing partners or upon termination of this Agreement.\n\n\n5. PAYMENT, CHARGES AND FEES.\n\nFees and charges payable by Merchant shall be as set forth in the Merchant Application and these Terms and Conditions. Merchant will be paid for indebtedness purchased under this Agreement by credit to Merchant's account(s). Each purchase of indebtedness shall be funded on a provisional basis until all chargebacks, fees, fines, penalties and other adjustments are identified and implemented in respect of such purchase under this Card Services Agreement and/or the rules and regulations of a card association or network organization. Accordingly, any such provisional funding is subject to reversal and recoupment with regard to any such chargebacks, fees, fines, penalties and other adjustments. Merchant's account(s) will be credited for the gross amount of the indebtedness deposited less the amount of any credit vouchers deposited. Merchant shall not be entitled to credit for any indebtedness that arises out of a transaction not processed in accordance with the terms of this Card Services Agreement or the rules and regulations of a card association or network organization. Chargebacks and adjustments will be charged to Merchant's account(s) on a daily basis. Merchant agrees to pay and Merchant's account(s) will be charged for the discount, fees, chargebacks and other fees and charges described in this Agreement.\n\n\n6. EQUIPMENT AND SUPPLIES/THIRD PARTY SERVICES.\n\nMerchant agrees that it will not acquire any title, copyrights, or any other proprietary right to any advertising material; leased equipment including imprinters, authorization terminals, or printers; software; credit card authenticators; unused forms; and Merchant deposit plastic cards provided by Easy Pay Direct, it's affiliated banking or processing partners in connection with this Card Services Agreement. Merchant will protect all such items from loss, theft, damage or any legal encumbrance and will allow Easy Pay Direct, its affiliated banking or processing partners and its designated representatives reasonable access to Merchant's premises for their repair, removal, modification, installation and relocation.\n\n\n7. FINANCIAL INFORMATION.\n\nMerchant agrees to furnish Easy Pay Direct, it's affiliated banking or processing partners and Member such financial statements and information concerning Merchant, its owners, principals, partners, proprietors or its affiliates as Easy Pay Direct, it's affiliated banking or processing partners may from time to time request. Easy Pay Direct, it's affiliated banking or processing partners, or its duly authorized representatives, may examine the books and records of Merchant, including records of all indebtedness previously purchased or presented for purchase. Merchant agrees to retain copies of all paper and electronic sales slips and credit slips submitted to Easy Pay Direct, it's affiliated banking or processing partners for a period of two years from submission.\n\n\n8. CHANGE IN BUSINESS.\n\nMerchant agrees to provide Easy Pay Direct, it's affiliated banking or processing partners and Member 60 days prior written notice of its intent to (a) transfer or sell any substantial part (10% or more) of its total stock, assets and/or to liquidate; or (b) change the basic nature of its business, or (c) convert all or part of the business to mail order sales, telephone order sales, or to other sales where the card is not present and swiped through Merchant's terminal.\n\n\n9. TRANSFERABILITY.\n\nThis Agreement is not transferable by Merchant without the written consent of Easy Pay Direct, it's affiliated banking or processing partners and Member. Any attempt by Merchant to assign its rights or to delegate its obligations in violation of this paragraph shall be void.\n\n\n10. WARRANTIES AND REPRESENTATIONS.\n\nMerchant warrants and represents to Easy Pay Direct, it's affiliated banking or processing partners and Member: (a) that each sales transaction delivered hereunder will represent a bona fide sale to a card holder by Merchant for the amount shown on the sales slip as the total sale and constitutes the binding obligation of the card holder, free from any claim, demand, defense, setoff or other adverse claim whatsoever; (b) that each sales slip or other evidence of indebtedness will accurately describe the goods and services which have been sold and delivered to the card holder or in accordance with his instructions; (c) that Merchant will comply fully with all federal, state and local laws, rules and regulations applicable to its business; (d) that Merchant will fulfill completely all of its obligations to the cardholder and will resolve any customer dispute or complaint directly with the card holder; (e) that all of the information contained in this Merchant Application and Service Agreement is true and correct.\n\n\n11. INDEMNITY.\n\nMerchant agrees to satisfy directly with the card holder any claim or complaint arising in connection with the card sale. Merchant agrees to indemnify and hold EasyPayDirect, it's affiliated banking or processing partners and Member harmless from and against any and all liabilities, losses, claims, damages, disputes, offsets, claims or counterclaims made by a cardholder or any other person or entity with regard to indebtedness sold by Merchant hereunder or any other Service provided hereunder.\n\n\n12. LIMITATION OF LIABILITY.\n\nNeither Member nor Easy Pay Direct, its affiliated banking or processing partners shall be liable for failure to provide the Services if such failure is due to any cause or condition beyond such party's reasonable control. The liability of Easy Pay Direct, it's affiliated banking or processing partners and Member for any loss hereunder shall, in the aggregate, be limited to actual, direct, and general money damages in an amount not to exceed one (1) month's average charge paid by Merchant hereunder for Services during the previous twelve (12) months.\n\n\n13. TERM AND TERMINATION.\n\nThis Agreement shall remain in full force and effect for an initial term of three (3) years. This Agreement shall be automatically extended for successive one (1) year periods on the same terms and conditions expressed herein, or as may be amended, unless Merchant gives written notice of termination at least 60 days prior to the expiration of the initial term or any extension or renewals thereof.\n\n\n14. RETURNED ITEMS/CHARGEBACKS.\n\nIf a card holder disputes any transaction, if a transaction is charged back for any reason by the card issuing institution, or if Easy Pay Direct, it's affiliated banking or processing partners or Member has any reason to believe an indebtedness previously purchased is questionable, not genuine, or is otherwise unacceptable, the amount of such indebtedness may be charged back and deducted from any payment due to Merchant or may be charged against any of Merchant's accounts or the Reserve Account.\n\n\n15. RESERVE ACCOUNT.\n\nAt any time, Easy Pay Direct, it's affiliated banking or processing partners and Member may, at their option, establish a reserve account to secure the performance of Merchant's obligations under this Agreement (\"Reserve Account\"). Any funds in the Reserve Account may be held until the later of (a) the expiration of any potentially applicable chargeback rights and (b) the period necessary to secure the performance of Merchant's obligations under this Card Services Agreement, which holding period may extend beyond termination of this Agreement.\n\n\n16. DEFAULT/SECURITY INTEREST.\n\nUpon failure by Merchant to meet any of its obligations under this Agreement (including funding the Reserve Account), any of the accounts referred to in Section 5 or any other accounts belonging to Merchant or Merchant's guarantor held by any designated depository may be debited without notice to Merchant.\n\n\n17. AMENDMENTS.\n\nThis Agreement may be amended only in writing signed by Easy Pay Direct, it's affiliated banking or processing partners, Member, and Merchant, except that the Card Acceptance Guide and any and all fees, charges, and/or discounts may be changed immediately.\n\n\n18. WAIVER.\n\nNo provision of this Agreement shall be deemed waived by any party unless such waiver is in writing and signed by the party against whom enforcement is sought.\n\n\n19. EXCHANGE OF INFORMATION.\n\nMerchant authorizes Easy Pay Direct, it's affiliated banking or processing partners to order a credit report on Merchant or any owner, officer, shareholder, partner, proprietor, managing agent or guarantor of Merchant.\n\n\n20. ONLINE STATEMENTS.\n\nIf Merchant elects to receive monthly statements by accessing them on-line (an \"E-statement\"), Merchant will need to visit and register at their processor's relevant URL to obtain a user ID and password.\n\n\n21. GENERAL.\n\nIf any provision of this Agreement or portion thereof is held to be unenforceable, such a determination will not affect the remainder of this Agreement. Paragraph headings are included for convenience only and are not to be used in interpreting this Agreement.\n\n\n22. NOTICES.\n\nAll notices required by this Agreement shall be in writing and shall be sent by telefax, by overnight carrier, or by regular or certified mail.\n\n\n23. TELEPHONE MONITORING AND CONTACTING THE MERCHANT.\n\nFrom time to time Easy Pay Direct, it's affiliated banking or processing partners and/or its agents may monitor and record telephone calls regarding Merchant's account to assure the quality of their service(s).\n\n\n24. MERGER.\n\nThe Agreement, including these Terms and Conditions and the Merchant Application, constitutes the entire Agreement between Merchant, Easy Pay Direct, it's affiliated banking or processing partners Direct, and Member and supersedes all prior memoranda or agreements relating thereto, whether oral or in writing.\n\n\n25. CHOICE OF LAW/ATTORNEY'S FEES/VENUE/JURY TRIAL WAIVER.\n\nShould it be necessary for Easy Pay Direct, it's affiliated banking or processing partners or Member to defend or enforce any of its rights under this Agreement in any collection or legal action, Merchant agrees to reimburse Easy Pay Direct, it's affiliate banking or processing partners and/or Member for all costs and expenses, including reasonable attorney's fees. Merchant waives trial by jury with respect to any litigation arising out of or relating to this Agreement. Any and all disputes shall be governed by the laws of the State of Georgia and shall be resolved on an individual basis without resort to any form of class action.\n\n\n26. EFFECTIVE DATE.\n\nThis Card Services Agreement shall become effective only upon acceptance by Easy Pay Direct, it's affiliated banking or processing partners and Member, or upon delivery of indebtedness at such locations as designated by Easy Pay Direct, it's affiliated banking or processing partners for purchase, whichever event shall first occur.\n\n\n27. DESIGNATION OF DEPOSITORY.\n\nThe financial institution set forth in the Merchant Application is designated by Merchant as a depository institution (\"Depository\") for its credit card indebtedness.\n\n\n28. FINANCIAL ACCOMMODATION.\n\nThe acquisition and processing of sales slips hereunder is a financial accommodation and, as such, in the event Merchant becomes a debtor in bankruptcy, this Agreement cannot be assumed or enforced, and Easy Pay Direct, it's affiliated banking or processing partners and Member shall be excused from performance hereunder.\n\n\n29. DEBIT/ATM PROCESSING SERVICES: ADDITIONAL TERMS AND CONDITIONS.\n\nDebit Sponsor shall act as Merchant's sponsor with respect to the participation of point-of-sale terminals in the following debit card networks: Accel, AFFN, Alaska Option, CU24, Interlink, Maestro, NYCE, Pulse, Shazam, Star, and Tyme.\n\n\n30. MERCHANT ACCEPTANCE OF EBT TRANSACTIONS: ADDITIONAL TERMS AND CONDITIONS.\n\nMerchant agrees to issue Benefits to Recipients in accordance with procedures specified herein and pursuant to the Quest Operating Rules, as amended from time-to-time, issued by the National Automated Clearing House Association.\n\n\n31. DISCOVER PROGRAM MARKS.\n\nMerchant is hereby granted a limited non-exclusive, non-transferable license to use Discover brands, emblems, trademarks, and/or logos that identify Discover cards (\"Discover Program Marks\").\n\n\n32. PRICING FOR SERVICES.\n\nPricing for services may vary based on banks, industry, location, size, marketing model and/or other risk factors and is at the discretion of Easy Pay Direct or its associated partners. By agreeing to these terms, you are agreeing to pricing of a minimum of $36 per month, 2.69% for qualified transactions, 3.79% for non qualified transactions, and $0.36 per transaction.\n\n\n33. MID AND NON-QUALIFIED SURCHARGES/CROSS-BORDER FEES.\n\nMerchant pricing appears in the Card Services Fee Schedule of the Merchant Application. Transactions that do not clear as priced are subject to MID or non-qualified surcharges that are billed back to you on your monthly statement.\n\n\nBy clicking to the terms below, I represent that I have read and am authorized to sign and submit this application on behalf of the entity above and all information I have provided herein is true, complete, and accurate.\n\nA MERCHANT'S SUBMISSION OF A TRANSACTION TO EASY PAY DIRECT SHALL BE DEEMED TO SIGNIFY MERCHANT'S ACCEPTANCE OF THE AGREEMENT, INCLUDING THE TERMS AND CONDITIONS HEREIN.</textarea>\n      </div>\n\n      <div class=\"terms-group\">\n        <input type=\"checkbox\" id=\"terms_agreed\" name=\"terms_and_conditions_agreed\" value=\"1\" required>\n        <label for=\"terms_agreed\">\n          I have read and accept the Terms and Conditions above\n          <span class=\"required\">*</span>\n        </label>\n      </div>\n      <span class=\"field-error\" id=\"err_terms_agreed\" style=\"display:block;margin-top:-10px;margin-bottom:10px\"></span>\n\n      <div class=\"btn-row\">\n        <button type=\"submit\" id=\"btn-step6\">Submit Application</button>\n      </div>\n    </form>\n\n    <!-- \u2500\u2500 Success \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n    <div id=\"success-panel\">\n      <div class=\"icon\">\u2705</div>\n      <h2>Application Submitted!</h2>\n      <p>Your merchant account application is complete. Easy Pay Direct will be in touch soon.</p>\n      <p id=\"success-uuid\" style=\"color:#6b7280;font-size:.85rem;margin-top:8px\"></p>\n    </div>\n\n  </div><!-- .card -->";

